@page "/notepad"
@rendermode InteractiveServer
@implements IAsyncDisposable
@inject IJSRuntime JS

<PageTitle>Notepad</PageTitle>

<h1>Notepad</h1>

<textarea class="form-control mb-3" rows="12" @bind="content" @bind:event="oninput"></textarea>

<div class="d-flex align-items-center gap-3 mb-3">
    <button class="btn btn-primary" @onclick="SaveNow">Save now</button>
    <button class="btn btn-outline-danger" @onclick="Clear">Clear</button>
    @if (lastSavedAt is not null)
    {
        <span class="text-muted">Last saved at @lastSavedAt.Value.ToString("HH:mm:ss")</span>
    }
</div>

@code {
    private string content = string.Empty;
    private string savedContent = string.Empty;
    private DateTime? lastSavedAt;
    private System.Threading.Timer? autoSaveTimer;
    private IJSObjectReference? module;
    private DotNetObjectReference<Notepad>? dotNetRef;

    private bool HasUnsavedChanges => content != savedContent;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            module = await JS.InvokeAsync<IJSObjectReference>(
                "import", $"./{Components.Layout.NavMenu.AssetUrl("Components/Pages/Notepad.razor.js")}");

            var restored = await module.InvokeAsync<string?>("load");
            if (restored is not null)
            {
                content = restored;
                savedContent = restored;
                StateHasChanged();
            }

            dotNetRef = DotNetObjectReference.Create(this);
            await module.InvokeVoidAsync("registerBeforeUnload", dotNetRef);

            autoSaveTimer = new System.Threading.Timer(
                async _ => await InvokeAsync(AutoSave), null,
                TimeSpan.FromSeconds(30), TimeSpan.FromSeconds(30));
        }
    }

    [JSInvokable]
    public bool GetHasUnsavedChanges() => HasUnsavedChanges;

    private async Task AutoSave()
    {
        if (HasUnsavedChanges)
        {
            await PersistContent();
            StateHasChanged();
        }
    }

    private async Task SaveNow()
    {
        await PersistContent();
    }

    private async Task PersistContent()
    {
        if (module is not null)
        {
            await module.InvokeVoidAsync("save", content);
            savedContent = content;
            lastSavedAt = DateTime.Now;
        }
    }

    private async Task Clear()
    {
        content = string.Empty;
        savedContent = string.Empty;
        lastSavedAt = null;
        if (module is not null)
        {
            await module.InvokeVoidAsync("clear");
        }
    }

    public async ValueTask DisposeAsync()
    {
        autoSaveTimer?.Dispose();

        if (module is not null)
        {
            await module.InvokeVoidAsync("unregisterBeforeUnload");
            await module.DisposeAsync();
        }
        dotNetRef?.Dispose();
    }
}

const storageKey = "notepad-content";

let dotNetRef = null;

function onBeforeUnload(e) {
    if (dotNetRef) {
        const hasChanges = dotNetRef.invokeMethod("GetHasUnsavedChanges");
        if (hasChanges) {
            e.preventDefault();
        }
    }
}

export function load() {
    return localStorage.getItem(storageKey);
}

export function save(content) {
    localStorage.setItem(storageKey, content);
}

export function clear() {
    localStorage.removeItem(storageKey);
}

export function registerBeforeUnload(ref) {
    dotNetRef = ref;
    window.addEventListener("beforeunload", onBeforeUnload);
}

export function unregisterBeforeUnload() {
    window.removeEventListener("beforeunload", onBeforeUnload);
    dotNetRef = null;
}

